package com.yeyamo_mobile.api.notification_service.infrastructure.channel;
import java.time.Instant;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.MediaType;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import com.fasterxml.jackson.databind.*;import com.yeyamo_mobile.api.notification_service.application.DevicePushTokenService;import com.yeyamo_mobile.api.notification_service.application.port.*;import com.yeyamo_mobile.api.notification_service.domain.*;import com.yeyamo_mobile.api.notification_service.infrastructure.persistence.*;
@Component public class PushChannelSender implements ChannelSender{private final RestClient client;private final ObjectMapper mapper;private final String endpoint;private final String accessToken;private final SpringPushTicketRepository tickets;private final DevicePushTokenRepositoryPort devices;private final DevicePushTokenService deviceService;public PushChannelSender(RestClient.Builder builder,ObjectMapper mapper,@Value("${notification.push.endpoint:https://exp.host/--/api/v2/push/send}")String endpoint,@Value("${notification.push.access-token:}")String token,SpringPushTicketRepository tickets,DevicePushTokenRepositoryPort devices,DevicePushTokenService deviceService){client=builder.build();this.mapper=mapper;this.endpoint=endpoint;accessToken=token;this.tickets=tickets;this.devices=devices;this.deviceService=deviceService;}public NotificationChannel channel(){return NotificationChannel.PUSH;}public void send(Delivery delivery,Notification notification){Map<String,Object>data=safeData(notification.dataJson());data.put("type",pushType(notification.eventType()));Map<String,Object>payload=new LinkedHashMap<>();payload.put("to",delivery.destination());payload.put("title",notification.title());payload.put("body",notification.eventType().equals("messaging.message.sent")?"Vous avez reçu un nouveau message":notification.body());payload.put("sound","default");payload.put("channelId",channel(notification.eventType()));payload.put("data",data);RestClient.RequestBodySpec request=client.post().uri(endpoint).contentType(MediaType.APPLICATION_JSON);if(accessToken!=null&&!accessToken.isBlank())request.header("Authorization","Bearer "+accessToken);JsonNode response=request.body(payload).retrieve().body(JsonNode.class);JsonNode result=response==null?null:response.path("data");if(result!=null&&result.isArray())result=result.path(0);String status=text(result,"status");String ticketId=text(result,"id");String error=text(result==null?null:result.path("details"),"error");String message=text(result,"message");DevicePushToken device=devices.findByToken(delivery.destination()).orElseThrow(()->new IllegalStateException("Push device not found"));PushTicketEntity ticket=new PushTicketEntity();ticket.id=UUID.randomUUID();ticket.deliveryId=delivery.id();ticket.deviceTokenId=device.id();ticket.expoTicketId=ticketId;ticket.status="ok".equals(status)?"ACCEPTED":"ERROR";ticket.errorCode=error;ticket.errorMessage=message;ticket.createdAt=Instant.now();tickets.save(ticket);if("DeviceNotRegistered".equals(error))deviceService.invalidate(delivery.destination());if(!"ok".equals(status))throw new ExpoPushException(error==null?"EXPO_PUSH_ERROR":error,message);}private Map<String,Object>safeData(String json){try{JsonNode source=mapper.readTree(json);Map<String,Object>result=new LinkedHashMap<>();for(String key:List.of("conversationId","eventId","ticketId","bookingId","campaignId","profileId","targetId")){JsonNode value=source.get(key);if(value!=null&&value.isValueNode())result.put(key,value.asText());}return result;}catch(Exception e){return new LinkedHashMap<>();}}private String channel(String type){if(type.startsWith("messaging."))return"messages";if(type.startsWith("booking."))return"bookings";if(type.startsWith("ticket."))return"tickets";if(type.startsWith("event."))return"events";if(type.startsWith("campaign."))return"promotions";if(type.startsWith("user.password"))return"security";if(type.startsWith("user.")||type.startsWith("social."))return"social";return"default";}private String pushType(String type){return switch(type){case"messaging.message.sent"->"MESSAGE_RECEIVED";case"booking.confirmed"->"BOOKING_CONFIRMED";case"booking.cancelled"->"BOOKING_CANCELLED";case"ticket.purchased","ticket.issued"->"TICKET_PURCHASED";case"campaign.approved"->"CAMPAIGN_APPROVED";case"campaign.rejected"->"CAMPAIGN_REJECTED";default->type.toUpperCase(Locale.ROOT).replace('.','_');};}private String text(JsonNode n,String field){JsonNode value=n==null?null:n.get(field);return value==null||value.isNull()?null:value.asText();}public static class ExpoPushException extends RuntimeException{private final String code;public ExpoPushException(String code,String message){super(message==null?code:message);this.code=code;}public String code(){return code;}}}
